'use strict';

// Runs the ordinary UI of an untouched production package. Test-only wallet
// material is generated by that UI, kept in memory, never logged or committed,
// and removed with the owned disposable profile. No node or payment is used.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const crypto = require('node:crypto');
const { startBrowser } = require('./fixtures/production-browser');

const source = path.resolve(process.env.SYRIUS_EXTENSION_DIR || path.join(__dirname, '..', 'build'));
let temporary, extensionDir, profileDir, cleanupPromise;
const password = () => 'Aa1!' + crypto.randomBytes(24).toString('hex');
const originalPassword = password();
const changedPassword = password();
const incorrectPassword = password();
const walletName = 'qualification-created';
const importedName = 'qualification-imported';
const quote = JSON.stringify;
let browser, browserStarting, page, phrase, stage = 'package validation';
const results = [];
const report = { package_version: null, package_tree_sha256: null, cases: results };
const launch = async () => {
  if (report.interrupted) throw Object.assign(new Error('Test interrupted.'), { code: 'TEST_INTERRUPTED' });
  browserStarting = startBrowser({ extensionDir, profileDir, setupScript });
  try { browser = await browserStarting; } finally { browserStarting = null; }
  if (report.interrupted) throw Object.assign(new Error('Test interrupted.'), { code: 'TEST_INTERRUPTED' });
};
const cleanup = () => cleanupPromise || (cleanupPromise = (async () => {
  if (browserStarting) {
    try { browser = await browserStarting; } catch { /* Startup cleans up its owned child on failure. */ }
  }
  if (browser) {
    try { await browser.stop(); } catch { report.cleanup_error = true; report.passed = false; process.exitCode = 1; }
  }
  phrase = null;
  try { if (temporary) fs.rmSync(temporary, { recursive: true, force: true }); }
  catch { report.cleanup_error = true; report.passed = false; process.exitCode = 1; }
  report.profile_removed = !temporary || !fs.existsSync(temporary);
  if (!report.profile_removed) { report.passed = false; process.exitCode = 1; }
  if (process.env.SYRIUS_LIFECYCLE_REPORT) {
    try { fs.writeFileSync(process.env.SYRIUS_LIFECYCLE_REPORT, JSON.stringify(report, null, 2) + '\n'); }
    catch { report.report_write_error = true; report.passed = false; process.exitCode = 1; }
  }
  console.log(JSON.stringify(report));
})());
for (const signal of ['SIGINT', 'SIGTERM']) process.once(signal, async () => {
  report.passed = false;
  report.interrupted = true;
  report.failed_stage = stage;
  process.exitCode = 1;
  await cleanup();
  process.exit(1);
});

const treeDigest = (dir) => {
  const files = [];
  const visit = (current, relative = '') => {
    for (const entry of fs.readdirSync(current, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
      assert(!entry.isSymbolicLink(), 'Package must not contain symlinks');
      const name = path.posix.join(relative, entry.name);
      if (entry.isDirectory()) visit(path.join(current, entry.name), name);
      else if (entry.isFile()) files.push([name, crypto.createHash('sha256').update(fs.readFileSync(path.join(current, entry.name))).digest('hex')]);
    }
  };
  visit(dir);
  return crypto.createHash('sha256').update(JSON.stringify(files)).digest('hex');
};

// Set connection preferences only, before startup. Never inject an encrypted
// wallet, decrypted key, SDK stub or development auto-unlock bridge.
const setupScript = `
if (!localStorage.getItem('currentNodeUrl')) localStorage.setItem('currentNodeUrl', 'wss://offline.invalid:1');
if (!localStorage.getItem('syrius.settings')) localStorage.setItem('syrius.settings', JSON.stringify({ autoReceive: false, autoLockMinutes: 15 }));
`;
const evaluate = expression => browser.evaluate(page, expression);
const until = (expression, label, timeout = 60000) => browser.until(page, expression, label, timeout);
const element = selector => `document.querySelector(${quote(selector)})`;
const fill = async (selector, value) => {
  assert(await evaluate(`(() => { const el = ${element(selector)}; if (!el) return false; const proto = el.tagName === 'TEXTAREA' ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype; Object.getOwnPropertyDescriptor(proto, 'value').set.call(el, ${quote(value)}); el.dispatchEvent(new Event('input', { bubbles: true })); el.dispatchEvent(new Event('change', { bubbles: true })); return true; })()`), 'Input is available');
};
const click = async selector => {
  assert(await evaluate(`(() => { const el = ${element(selector)}; if (!el || el.disabled) return false; el.click(); return true; })()`), 'Action is available');
};
const clickText = async text => {
  assert(await evaluate(`(() => { const el = [...document.querySelectorAll('button,[role="button"],.burger-popover-item')].find(e => e.textContent.trim() === ${quote(text)}); if (!el || el.disabled) return false; el.click(); return true; })()`), 'Named action is available');
};
const route = async (destination, selector) => {
  await evaluate(`location.hash = ${quote('#' + destination)}`);
  await until(`Boolean(${element(selector)})`, 'route ready');
};
const snapshot = async name => evaluate(`(async () => {
  const raw = localStorage.getItem('znn.ts-wallet');
  const wallets = JSON.parse(raw || '{}'); const entry = wallets[${quote(name)}];
  if (!entry) return null;
  const digest = async value => [...new Uint8Array(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(value)))].map(b => b.toString(16).padStart(2, '0')).join('');
  const session = (await chrome.storage.session.get('znn.unlock'))['znn.unlock'];
  const persistent = JSON.stringify({ web: Object.fromEntries(Object.keys(localStorage).map(key => [key, localStorage.getItem(key)])), local: await chrome.storage.local.get(null), sync: await chrome.storage.sync.get(null) });
  return {
    identity: await digest(JSON.stringify(entry.baseAddress)),
    encrypted: await digest(JSON.stringify(entry)),
    encryptedShape: entry.version === 1 && entry.crypto?.cipherName === 'aes-256-gcm' && entry.crypto?.kdf === 'argon2.IDKey' && Boolean(entry.crypto?.cipherData) && Boolean(entry.crypto?.nonce) && Boolean(entry.crypto?.argon2Params?.salt),
    noPersistentPhraseOrPassword: !persistent.includes(${quote(phrase)}) && !persistent.includes(${quote(originalPassword)}) && !persistent.includes(${quote(changedPassword)}) && (!session?.entropy || !persistent.includes(session.entropy)) && !Object.hasOwn(entry, 'entropy') && !Object.hasOwn(entry, 'mnemonic') && !Object.hasOwn(entry, 'password')
  };
})()`);
const casePassed = label => { results.push({ name: label, passed: true }); console.log('PASS: ' + label); };
const revokedSession = `(async () => { const values = await chrome.storage.session.get(['znn.unlock', 'znn.publicState']); const record = values['znn.unlock']; return (!record || record.locked === true) && !record?.entropy && !values['znn.publicState']; })()`;
const locked = async ({ strict = true } = {}) => {
  await until(`location.hash === '#/password' && Boolean(${element('input[name="passwordField"]')})`, 'locked screen');
  assert(await evaluate(`document.querySelectorAll('.mnemonic-original-word').length === 0`), 'Backup DOM is removed on lock');
  assert(await evaluate(strict ? revokedSession : `(async () => { const values = await chrome.storage.session.get(['znn.unlock', 'znn.publicState']); return !values['znn.unlock']?.entropy && !values['znn.publicState']; })()`), 'Shared secret and public state are revoked');
};
const lock = async () => { await click('[aria-label="Menu"]'); await clickText('Lock wallet'); await locked(); };
const unlock = async (value, success) => {
  await fill('input[name="passwordField"]', value);
  await click('button[type="submit"]');
  if (success) await until(`location.hash.startsWith('#/tabs/') && Boolean(${element('[aria-label="Menu"]')})`, 'wallet unlocked');
  else {
    await until(`[...document.querySelectorAll('.input-error')].some(e => e.textContent.includes('Wrong password')) && !${element('button[type="submit"]')}.disabled`, 'wrong password rejected');
    assert(await evaluate(revokedSession), 'Wrong password cannot publish an unlock');
  }
};

(async () => {
  try {
    temporary = fs.mkdtempSync(path.join(os.tmpdir(), 'syrius-keyfile-lifecycle-'));
    fs.chmodSync(temporary, 0o700);
    extensionDir = path.join(temporary, 'extension');
    profileDir = path.join(temporary, 'profile');
    const manifest = JSON.parse(fs.readFileSync(path.join(source, 'manifest.json'), 'utf8'));
    assert.equal(manifest.manifest_version, 3, 'Manifest V3 package required');
    assert(manifest.content_security_policy.extension_pages.includes('wasm-unsafe-eval'), 'Original WASM policy required');
    for (const file of ['popup.html', 'popup.bundle.js', 'vendors.bundle.js', manifest.background.service_worker]) assert(fs.statSync(path.join(source, file)).isFile(), 'Production entrypoint required');
    fs.cpSync(source, extensionDir, { recursive: true });
    report.package_version = manifest.version;
    report.package_tree_sha256 = treeDigest(source);
    assert.equal(treeDigest(extensionDir), report.package_tree_sha256, 'Package copied without changes');
    await launch();
    report.browser = browser.browserVersion;
    page = await browser.openPage('/auth/get-started');
    await until(`Boolean(${element('input[name="walletNameField"]')})`, 'creation form');
    stage = 'create and persistence failure';
    await fill('input[name="walletNameField"]', walletName);
    await fill('input[name="passwordField"]', originalPassword);
    await fill('input[name="repeatPasswordField"]', originalPassword);
    await click('button[type="submit"]');
    await until(`Boolean(${element('.secret-phrase-text')}) && Boolean(${element('#agree_phrase')})`, 'fresh phrase generated');
    phrase = await evaluate(`${element('.secret-phrase-text')}.textContent.trim()`);
    assert([12, 24].includes(phrase.split(' ').length), 'Generated phrase has supported length');
    await click('#agree_phrase');
    await clickText('Continue');
    await until(`Boolean(${element('.secret-words .secret-word')})`, 'phrase confirmation');
    for (const word of phrase.split(' ')) {
      assert(await evaluate(`(() => { const el = [...document.querySelectorAll('.secret-words .secret-word')].find(e => e.textContent.trim() === ${quote(word)}); if (!el) return false; el.click(); return true; })()`), 'Generated word can be confirmed');
    }
    // A one-shot storage-boundary fault follows real encryption. It does not
    // replace Argon2, AES, the SDK, or the application's save callback.
    await evaluate(`(() => { globalThis.__qualificationWriteFailed = false; globalThis.__restoreQualificationStorage = Storage.prototype.setItem; Storage.prototype.setItem = function(key, value) { if (key === 'znn.ts-wallet') { globalThis.__qualificationWriteFailed = true; Storage.prototype.setItem = globalThis.__restoreQualificationStorage; throw new DOMException('Synthetic test write failure', 'QuotaExceededError'); } return globalThis.__restoreQualificationStorage.call(this, key, value); }; return true; })()`);
    await clickText('Create wallet');
    await until(`globalThis.__qualificationWriteFailed === true && Storage.prototype.setItem === globalThis.__restoreQualificationStorage && !${element('button.button.primary')}.disabled && ${element('button.button.primary')}.textContent.trim() === 'Create wallet'`, 'write failure recovers');
    assert(await evaluate(`!Object.hasOwn(JSON.parse(localStorage.getItem('znn.ts-wallet') || '{}'), ${quote(walletName)})`), 'Failed persistence creates no wallet');
    assert(await evaluate(revokedSession), 'Failed persistence creates no unlock');
    casePassed('real encryption followed by rejected persistence is retryable');
    await clickText('Create wallet');
    await until(`location.hash === '#/tabs/dashboard' && Boolean(${element('[aria-label="Menu"]')})`, 'creation completed');
    const created = await snapshot(walletName);
    assert(created?.encryptedShape && created.noPersistentPhraseOrPassword, 'Only encrypted keyfile persists');
    casePassed('UI creation persists a real encrypted SDK keyfile');

    stage = 'password rejection and backup';
    await lock();
    await unlock(incorrectPassword, false);
    await unlock(originalPassword, true);
    casePassed('wrong password fails and correct password unlocks');
    await route('/tabs/settings/export-mnemonic', 'input[name="inputPasswordField"]');
    await fill('input[name="inputPasswordField"]', incorrectPassword);
    await click('button[type="submit"]');
    await until(`[...document.querySelectorAll('.input-error')].some(e => e.textContent.includes('Wrong password')) && !${element('button[type="submit"]')}.disabled`, 'backup password rejected');
    assert(await evaluate(`document.querySelectorAll('.mnemonic-original-word').length === 0`), 'Rejected backup has no secret DOM');
    await fill('input[name="inputPasswordField"]', originalPassword);
    await click('button[type="submit"]');
    await until(`document.querySelectorAll('.mnemonic-original-word').length > 0`, 'backup revealed');
    assert(await evaluate(`[...document.querySelectorAll('.mnemonic-original-word')].map(e => e.textContent.trim()).join(' ') === ${quote(phrase)}`), 'Real decrypted backup matches generated phrase');
    casePassed('password-gated backup recovers the generated phrase');
    const other = await browser.openPage('/tabs/settings/export-mnemonic');
    await browser.until(other, `Boolean(document.querySelector('input[name="inputPasswordField"]'))`, 'second popup restored', 60000);
    await browser.evaluate(other, `(() => { const el = document.querySelector('input[name="inputPasswordField"]'); Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set.call(el, ${quote(originalPassword)}); el.dispatchEvent(new Event('input', { bubbles: true })); document.querySelector('button[type="submit"]').click(); return true; })()`);
    await browser.until(other, `document.querySelectorAll('.mnemonic-original-word').length > 0`, 'second backup revealed', 60000);
    await lock();
    await browser.until(other, `location.hash === '#/password' && document.querySelectorAll('.mnemonic-original-word').length === 0`, 'other popup revoked', 60000);
    await browser.closePage(other);
    casePassed('explicit lock removes backup DOM in both extension pages');

    stage = 'password rotation';
    await unlock(originalPassword, true);
    await route('/tabs/settings/change-password', 'input[name="currentPasswordField"]');
    await fill('input[name="currentPasswordField"]', incorrectPassword);
    await fill('input[name="newPasswordField"]', changedPassword);
    await fill('input[name="confirmPasswordField"]', changedPassword);
    await click('button[type="submit"]');
    await until(`[...document.querySelectorAll('.input-error')].some(e => e.textContent.includes('Wrong password')) && !${element('button[type="submit"]')}.disabled`, 'rotation rejects wrong password');
    assert.equal((await snapshot(walletName)).encrypted, created.encrypted, 'Rejected rotation preserves encrypted entry');
    await fill('input[name="currentPasswordField"]', originalPassword);
    await click('button[type="submit"]');
    await until(`location.hash === '#/tabs/settings'`, 'password changed');
    const rotated = await snapshot(walletName);
    assert(rotated.encryptedShape && rotated.noPersistentPhraseOrPassword && rotated.identity === created.identity && rotated.encrypted !== created.encrypted, 'Rotation preserves identity and changes encrypted entry');
    await lock();
    await unlock(originalPassword, false);
    await unlock(changedPassword, true);
    casePassed('rotation retains identity and replaces the accepted password');
    await route('/tabs/settings/export-mnemonic', 'input[name="inputPasswordField"]');
    await fill('input[name="inputPasswordField"]', changedPassword);
    await click('button[type="submit"]');
    await until(`document.querySelectorAll('.mnemonic-original-word').length > 0`, 'rotated backup revealed');
    assert(await evaluate(`[...document.querySelectorAll('.mnemonic-original-word')].map(e => e.textContent.trim()).join(' ') === ${quote(phrase)}`), 'Rotation preserves recovery phrase');
    casePassed('backup remains identical after password rotation');

    stage = 'popup reopen and browser restart';
    await browser.closePage(page);
    page = await browser.openPage('/tabs/dashboard');
    await until(`location.hash === '#/tabs/dashboard' && Boolean(${element('[aria-label="Menu"]')})`, 'timed session restores in reopened popup');
    assert.equal((await snapshot(walletName)).encrypted, rotated.encrypted, 'Popup reopen preserves encrypted entry');
    casePassed('timed session restores after extension document closure');

    stage = 'on-close policy';
    await route('/tabs/settings', '.segmented-option');
    await clickText('On close');
    await until(`(async () => { const record = (await chrome.storage.session.get('znn.unlock'))['znn.unlock']; const selected = [...document.querySelectorAll('.segmented-option')].find(e => e.textContent.trim() === 'On close'); return record?.mode === 'local' && record.minutes === 0 && !record.entropy && !record.privateUntil && JSON.parse(localStorage.getItem('syrius.settings') || '{}').autoLockMinutes === 0 && selected?.classList.contains('is-selected') && !selected.disabled; })()`, 'private session policy');
    assert(await evaluate(`!(await chrome.storage.session.get('znn.publicState'))['znn.publicState']`), 'On-close policy publishes no public unlock');
    await browser.closePage(page);
    page = await browser.openPage();
    await locked({ strict: false });
    await unlock(changedPassword, true);
    casePassed('on-close owner cannot restore after its document closes');

    stage = 'natural five-minute expiry';
    await route('/tabs/settings', '.segmented-option');
    await clickText('5 min');
    await until(`(async () => { const record = (await chrome.storage.session.get('znn.unlock'))['znn.unlock']; return record?.mode === 'timed' && record.minutes === 5; })()`, 'five-minute policy');
    const naturalExpiresAt = await evaluate(`(async () => (await chrome.storage.session.get('znn.unlock'))['znn.unlock'].expiresAt)()`);
    assert(Number.isFinite(naturalExpiresAt) && naturalExpiresAt - Date.now() > 290000 && naturalExpiresAt - Date.now() <= 305000, 'Five-minute deadline is scheduled');
    const expiryPage = await browser.openPage('/tabs/settings/export-mnemonic');
    await browser.until(expiryPage, `Boolean(document.querySelector('input[name="inputPasswordField"]'))`, 'expiry backup ready', 60000);
    await browser.evaluate(expiryPage, `(() => { const el = document.querySelector('input[name="inputPasswordField"]'); Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set.call(el, ${quote(changedPassword)}); el.dispatchEvent(new Event('input', { bubbles: true })); document.querySelector('button[type="submit"]').click(); return true; })()`);
    await browser.until(expiryPage, `document.querySelectorAll('.mnemonic-original-word').length > 0`, 'expiry backup revealed', 60000);
    console.log('WAIT: natural five-minute expiry (no clock or session-record changes)');
    const expiryDeadline = naturalExpiresAt + 30000;
    let expiryObserved = false;
    while (Date.now() < expiryDeadline) {
      if (await evaluate(`location.hash === '#/password'`)) {
        const observedAt = Date.now();
        assert(observedAt >= naturalExpiresAt - 2000 && observedAt <= expiryDeadline, 'Session lock is observed within deadline bounds');
        expiryObserved = true;
        break;
      }
      await new Promise(resolve => setTimeout(resolve, 1000));
    }
    assert(expiryObserved, 'Session locks no later than thirty seconds after its deadline');
    await locked();
    await browser.until(expiryPage, `location.hash === '#/password' && document.querySelectorAll('.mnemonic-original-word').length === 0`, 'natural expiry removes other backup', 15000);
    await browser.closePage(expiryPage);
    await unlock(changedPassword, true);
    casePassed('natural five-minute deadline revokes both extension pages');

    stage = 'browser restart';
    console.log('CHECK: browser restart shutdown boundary');
    const firstId = browser.id;
    report.first_browser_network = { ...browser.stats };
    await browser.stop(); browser = null;
    await launch();
    assert.equal(browser.id, firstId, 'Same install path retains extension identity');
    page = await browser.openPage();
    await locked();
    assert.equal((await snapshot(walletName)).encrypted, rotated.encrypted, 'Browser restart preserves only encrypted persistent wallet');
    await unlock(changedPassword, true);
    casePassed('full browser restart requires password and preserves keyfile');

    stage = 'same-package reload';
    await browser.reloadExtension();
    page = await browser.openPage();
    await locked();
    assert.equal((await snapshot(walletName)).encrypted, rotated.encrypted, 'Extension reload preserves encrypted entry');
    await unlock(changedPassword, true);
    casePassed('runtime reload and same-path re-registration clear unlock and preserve keyfile');

    stage = 'recovery import and removal';
    await lock();
    await route('/auth/recovery', 'textarea');
    await fill('textarea', phrase);
    await clickText('Continue');
    await until(`Boolean(${element('input[name="walletNameField"]')})`, 'import form');
    await fill('input[name="walletNameField"]', importedName);
    await fill('input[name="passwordField"]', originalPassword);
    await fill('input[name="repeatPasswordField"]', originalPassword);
    await click('button[type="submit"]');
    await until(`location.hash === '#/tabs/dashboard' && Boolean(${element('[aria-label="Menu"]')})`, 'import completed');
    const imported = await snapshot(importedName);
    assert(imported.encryptedShape && imported.noPersistentPhraseOrPassword && imported.identity === created.identity && imported.encrypted !== rotated.encrypted, 'Recovery import preserves identity with independent encryption');
    casePassed('generated backup imports with matching account identity');
    await route('/tabs/settings/reset-wallet', 'input[placeholder="Wallet password"]');
    await fill('input[placeholder="Wallet password"]', incorrectPassword);
    await fill('input[placeholder="Type REMOVE to confirm"]', 'REMOVE');
    await until(`![...document.querySelectorAll('.Toastify__toast--error')].some(e => e.textContent.includes('Wrong password.'))`, 'prior password errors dismissed');
    await clickText('Remove');
    await until(`[...document.querySelectorAll('.Toastify__toast--error')].some(e => e.textContent.includes('Wrong password.')) && ![...document.querySelectorAll('button')].find(e => e.textContent.trim() === 'Remove').disabled`, 'removal rejects wrong password');
    assert.equal((await snapshot(importedName)).encrypted, imported.encrypted, 'Wrong removal password preserves wallet');
    await fill('input[placeholder="Wallet password"]', originalPassword);
    await clickText('Remove');
    await locked();
    assert.equal(await snapshot(importedName), null, 'Only selected wallet is removed');
    assert.equal((await snapshot(walletName)).encrypted, rotated.encrypted, 'Same-seed original wallet remains intact');
    await unlock(changedPassword, true);
    casePassed('password-gated removal revokes unlock and preserves other wallet');
    await route('/tabs/settings/reset-wallet', 'input[placeholder="Wallet password"]');
    await fill('input[placeholder="Wallet password"]', changedPassword);
    await fill('input[placeholder="Type REMOVE to confirm"]', 'REMOVE');
    await clickText('Remove');
    await until(`location.hash === '#/auth/onboarding'`, 'last wallet removed');
    assert.equal(await snapshot(walletName), null, 'Last encrypted wallet removed');
    assert(await evaluate(revokedSession), 'Last removal revokes shared unlock');
    casePassed('last-wallet removal returns to onboarding');

    report.last_browser_network = { ...browser.stats };
    assert(report.first_browser_network.wasmModules > 0, 'Real browser WASM compilation observed');
    assert.equal(treeDigest(extensionDir), report.package_tree_sha256, 'Production members remain untouched');
    report.same_package_reload_only = true;
    report.version_migration_qualified = false;
    report.live_chain_qualified = false;
    report.native_node_argon2_qualified = false;
    report.persistence_failure_is_instrumented = true;
    report.passed = true;
  } catch (error) {
    report.passed = false;
    report.failed_stage = stage;
    report.failure_code = error.code || 'ASSERTION_FAILED';
    if (browser && page) {
      try { report.failure_observation = await evaluate(`({ route: location.hash.split('?')[0], named_inputs: [...document.querySelectorAll('input[name]')].map(e => e.name), backup_nodes: document.querySelectorAll('.mnemonic-original-word').length, error_toast: Boolean(document.querySelector('.Toastify__toast--error')), injected_write_failed: globalThis.__qualificationWriteFailed === true, create_button_busy: [...document.querySelectorAll('button')].some(e => e.textContent.trim() === 'Creating…') })`); } catch { /* Diagnostics are optional and never include secrets. */ }
      report.network_at_failure = { ...browser.stats };
    }
    // Never print a DOM dump, evaluated expression, underlying exception or
    // assertion values: those may contain the freshly generated test material.
    console.error('FAIL: ' + stage);
    process.exitCode = 1;
  } finally {
    await cleanup();
  }
})();
